"""Frontier-labeled curated HEAD (audit 2026-09-02, green I2).

The unresolved industry head is steep: 2,313 companies lift L1 step coverage
from 53% to 60%, and every one of them carries a LinkedIn company_id, employee
titles and job descriptions. This module holds the labels from the frontier
pass over that head, keyed on ``company_id`` like ``curated_promoted.PROMOTED``.

Provenance contract:
- ``METHOD`` names the pass; bump it when the labeling protocol changes.
- Labels are at the deepest depth the labeler was confident about; genuinely
  diversified firms get ``XDV``; staffing/contract employers get ``PRO.HRST``.
- A blind second pass on a fixed sample gates the tier (see the audit's open
  decision 2); the gate result and sample live in ``industry/results/``.
- Precedence in ``curated.CURATED``: hand-curated > HEAD > PROMOTED.
- Never label a key that ``curated.RETRACTED`` lists; never regenerate this
  file from a vote cache without re-gating.

Generated by scratchpad/head_label_writer.py from the labeled JSONL; edit the
JSONL, not this file.
"""

